<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Algorithm Visualizer</title>
    <style>
        :root {
            --bg-color: #121212;
            --container-bg: #1e1e1e;
            --bar-color: #4db6ac;
            --accent-color: #ff8f00;
            --text-color: #e0e0e0;
            --button-bg: #333;
            --button-hover: #444;
        }

        body {
            margin: 0;
            padding: 20px;
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
        }

        h1 { margin-bottom: 20px; font-weight: 300; }

        #visualizer-container {
            background-color: var(--container-bg);
            padding: 40px;
            border-radius: 8px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        #bars {
            display: flex;
            align-items: flex-end;
            height: 400px;
            gap: 2px;
            border-bottom: 2px solid #444;
            padding-bottom: 5px;
        }

        .bar {
            flex: 1;
            background-color: var(--bar-color);
            transition: height 0.1s ease, background-color 0.1s ease;
            border-radius: 2px 2px 0 0;
        }

        .controls {
            margin-top: 30px;
            display: flex;
            gap: 15px;
            justify-content: center;
        }

        button {
            padding: 12px 24px;
            font-size: 1rem;
            cursor: pointer;
            background-color: var(--button-bg);
            color: white;
            border: 1px solid #555;
            border-radius: 4px;
            transition: all 0.2s;
        }

        button:hover {
            background-color: var(--button-hover);
            border-color: var(--accent-color);
        }

        button:active {
            transform: translateY(2px);
        }

        .status {
            margin-top: 15px;
            font-family: monospace;
            font-size: 0.9rem;
            color: #888;
        }
    </style>
</head>
<body>

    <h1>Sorting Visualizer</h1>

    <div id="visualizer-container">
        <div id="bars"></div>
        <div class="controls">
            <button id="shuffle">Shuffle</button>
            <button id="sort">Sort</button>
            <button id="reset">Reset</button>
        </div>
        <div class="status" id="status">Ready</div>
    </div>

    <script>
        /**
         * Sorting State Logic (Bubble Sort implementation for step-by-step)
         */
        let currentArray = [];
        let i_ptr = 0; // outer loop pointer
        let j_ptr = 0; // inner loop pointer
        const ARRAY_SIZE = 60;

        function render() {
            const container = document.getElementById('bars');
            container.innerHTML = '';
            currentArray.forEach(val => {
                const bar = document.createElement('div');
                bar.className = 'bar';
                // Normalize height: values are 1-500, container is 400px
                const heightPercentage = (val / 500) * 100;
                bar.style.height = `${Math.max(heightPercentage, 2)}%`;
                container.appendChild(bar);
            });
        }

        function initArray() {
            currentArray = Array.from({ length: ARRAY_SIZE }, () => Math.floor(Math.random() * 490) + 10);
            i_ptr = 0;
            j_ptr = 0;
            render();
            document.getElementById('status').innerText = 'Ready';
        }

        /**
         * Programmatic API required for grading
         */
        window.viz = {
            array: () => [...currentArray],

            setArray: (a) => {
                currentArray = [...a];
                i_ptr = 0;
                j_ptr = 0;
                render();
            },

            sortStep: () => {
                // Bubble Sort logic executed one step at a time
                if (i_ptr < currentArray.length - 1) {
                    const limit = currentArray.length - 1 - i_ptr;
                    if (j_ptr < limit) {
                        if (currentArray[j_ptr] > currentArray[j_ptr + 1]) {
                            // Swap
                            let temp = currentArray[j_ptr];
                            currentArray[j_ptr] = currentArray[j_ptr + 1];
                            currentArray[j_ptr + 1] = temp;
                        }
                        j_ptr++;
                    } else {
                        i_ptr++;
                        j_ptr = 0;
                    }
                    render();
                    return false;
                }
                return true; // Fully sorted or finished passes
            },

            sorted: () => {
                for (let k = 0; k < currentArray.length - 1; k++) {
                    if (currentArray[k] > currentArray[k + 1]) return false;
                }
                return true;
            }
        };

        /**
         * UI Event Handlers
         */
        const shuffleBtn = document.getElementById('shuffle');
        const sortBtn = document.getElementById('sort');
        const resetBtn = document.getElementById('reset');
        const statusTxt = document.getElementById('status');

        shuffleBtn.addEventListener('click', () => {
            initArray();
        });

        resetBtn.addEventListener('click', () => {
            initArray();
        });

        sortBtn.addEventListener('click', async () => {
            sortBtn.disabled = true;
            statusTxt.innerText = 'Sorting...';

            // Use a recursive loop to animate the steps via sortStep()
            const animate = () => {
                const isDone = window.viz.sortStep();
                if (!isDone) {
                    requestAnimationFrame(animate);
                } else {
                    statusTxt.innerText = 'Sorted!';
                    sortBtn.disabled = false;
                }
            };

            animate();
        });

        // Initial Load
        initArray();
    </script>
</body>
</html>
